#![allow(clippy::expect_used)]

//! Integration tests for `chronofork megadrive cartridge` and `megadrive boot`.
//!
//! The ROMs are generated by the crate (`cartridge_boot_rom`, `demo_rom`), so no
//! commercial image is read or embedded. SRAM import/export is exercised over
//! temporary files with the canonical 64 KiB length.

mod common;

use std::path::Path;

use chronofork_megadrive::{MAX_IMAGE_SIZE, boot_marker, cartridge_boot_rom};
use common::{path_str, run, temp_dir, write_rom};

fn write_bytes(dir: &Path, name: &str, bytes: &[u8]) -> std::path::PathBuf {
    let path = dir.join(name);
    std::fs::write(&path, bytes).expect("write fixture");
    path
}

#[test]
fn cartridge_command_prints_header_facts() {
    let dir = temp_dir("cartridge-facts");
    let rom = write_bytes(&dir, "boot.rom", &cartridge_boot_rom());
    let output = run(&["megadrive", "cartridge", "--rom", path_str(&rom)]);
    let stdout = String::from_utf8(output.stdout).expect("utf8");
    let stderr = String::from_utf8(output.stderr).expect("utf8");
    assert!(output.status.success(), "cartridge failed:\n{stderr}");
    assert!(stderr.is_empty(), "cartridge wrote to stderr:\n{stderr}");
    for expected in [
        "system=SEGA MEGA DRIVE",
        "region=JUE",
        "serial=GM 00000000-00",
        "checksum_ok=true",
        "sram_declared=false",
        "mapper_banks=1,2,3,4,5,6,7",
        "PASS",
    ] {
        assert!(
            stdout.contains(expected),
            "cartridge output is missing `{expected}`:\n{stdout}"
        );
    }
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn cartridge_sram_import_export_round_trips_and_is_typed() {
    let dir = temp_dir("cartridge-sram");
    let rom = write_bytes(&dir, "boot.rom", &cartridge_boot_rom());
    let imported = write_bytes(&dir, "save.bin", &[0x07_u8; 65_536]);
    let exported = dir.join("export.bin");

    let output = run(&[
        "megadrive",
        "cartridge",
        "--rom",
        path_str(&rom),
        "--sram-in",
        path_str(&imported),
        "--sram-out",
        path_str(&exported),
    ]);
    let stderr = String::from_utf8(output.stderr).expect("utf8");
    assert!(output.status.success(), "sram round trip failed:\n{stderr}");
    assert_eq!(
        std::fs::read(&exported).expect("exported SRAM"),
        vec![0x07_u8; 65_536]
    );

    let short = write_bytes(&dir, "short.bin", &[0_u8; 1024]);
    let output = run(&[
        "megadrive",
        "cartridge",
        "--rom",
        path_str(&rom),
        "--sram-in",
        path_str(&short),
    ]);
    let stderr = String::from_utf8(output.stderr).expect("utf8");
    assert!(!output.status.success(), "a short SRAM import must fail");
    assert!(
        stderr.contains("65536"),
        "the short-import error must name the canonical length:\n{stderr}"
    );
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn boot_command_reaches_the_marker_with_tmss_enabled() {
    let dir = temp_dir("boot-marker");
    let rom = write_bytes(&dir, "boot.rom", &cartridge_boot_rom());
    let output = run(&[
        "megadrive",
        "boot",
        "--rom",
        path_str(&rom),
        "--frames",
        "1",
        "--tmss",
        "enabled",
    ]);
    let stdout = String::from_utf8(output.stdout).expect("utf8");
    let stderr = String::from_utf8(output.stderr).expect("utf8");
    assert!(output.status.success(), "boot failed:\n{stderr}");
    assert!(stderr.is_empty(), "boot wrote to stderr:\n{stderr}");
    for expected in [
        "reached_marker=true",
        format!("pc=0x{:08X}", boot_marker()).as_str(),
        "tick=",
        "state_hash=",
        "tmss=enabled",
        "PASS",
    ] {
        assert!(
            stdout.contains(expected),
            "boot output is missing `{expected}`:\n{stdout}"
        );
    }
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn boot_command_exits_non_zero_when_the_marker_is_not_reached() {
    let dir = temp_dir("boot-miss");
    // The demo ROM loops forever at 0x26A, never at the boot marker.
    let rom = write_bytes(&dir, "demo.rom", &chronofork_megadrive::demo_rom());
    let output = run(&[
        "megadrive",
        "boot",
        "--rom",
        path_str(&rom),
        "--frames",
        "1",
    ]);
    let stdout = String::from_utf8(output.stdout).expect("utf8");
    let stderr = String::from_utf8(output.stderr).expect("utf8");
    assert!(
        !output.status.success(),
        "an unreached marker must exit non-zero"
    );
    assert!(
        stdout.contains("reached_marker=false"),
        "the report must still name the miss:\n{stdout}"
    );
    assert!(
        stderr.contains("boot marker"),
        "the failure must name the marker:\n{stderr}"
    );
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn usage_and_subcommand_errors_name_the_new_surfaces() {
    let output = run(&["help"]);
    let stdout = String::from_utf8(output.stdout).expect("utf8");
    assert!(stdout.contains("chronofork megadrive cartridge --rom <FILE>"));
    assert!(stdout.contains("chronofork megadrive boot --rom <FILE>"));

    let output = run(&["megadrive", "nope"]);
    let stderr = String::from_utf8(output.stderr).expect("utf8");
    assert!(!output.status.success());
    assert!(
        stderr.contains("expected demo, trace, cartridge or boot"),
        "the subcommand error must list the surfaces:\n{stderr}"
    );
}

#[test]
fn invalid_cartridge_and_boot_options_are_typed_errors() {
    let dir = temp_dir("cartridge-errors");
    let short = write_bytes(&dir, "short.rom", &[0_u8; 7]);
    let output = run(&["megadrive", "cartridge", "--rom", path_str(&short)]);
    let stderr = String::from_utf8(output.stderr).expect("utf8");
    assert!(!output.status.success());
    assert!(stderr.contains("invalid cartridge"), "{stderr}");

    let rom = write_bytes(&dir, "boot.rom", &cartridge_boot_rom());
    let output = run(&[
        "megadrive",
        "boot",
        "--rom",
        path_str(&rom),
        "--frames",
        "0",
    ]);
    let stderr = String::from_utf8(output.stderr).expect("utf8");
    assert!(!output.status.success());
    assert!(stderr.contains("at least 1"), "{stderr}");

    let output = run(&[
        "megadrive",
        "boot",
        "--rom",
        path_str(&rom),
        "--tmss",
        "maybe",
    ]);
    let stderr = String::from_utf8(output.stderr).expect("utf8");
    assert!(!output.status.success());
    assert!(stderr.contains("enabled` or `disabled"), "{stderr}");
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn cartridge_command_reports_the_shared_synthetic_rom_facts() {
    // Exercises the shared `write_rom`/`synthetic_rom` fixture so the common
    // module has no unused helper in this test binary.
    let dir = temp_dir("cartridge-shared");
    let rom = write_rom(&dir);
    let output = run(&["megadrive", "cartridge", "--rom", path_str(&rom)]);
    let stdout = String::from_utf8(output.stdout).expect("utf8");
    let stderr = String::from_utf8(output.stderr).expect("utf8");
    assert!(output.status.success(), "cartridge failed:\n{stderr}");
    assert!(stderr.is_empty(), "cartridge wrote to stderr:\n{stderr}");
    for expected in [
        "system=SEGA MEGA DRIVE",
        "region=JUE",
        "serial=GM 00000000-00",
        "sram_declared=false",
        "checksum_ok=true",
        "PASS",
    ] {
        assert!(
            stdout.contains(expected),
            "shared-ROM cartridge output is missing `{expected}`:\n{stdout}"
        );
    }
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn cartridge_and_boot_reject_an_oversized_rom_before_reading() {
    let dir = temp_dir("cartridge-oversized");
    let path = dir.join("large.rom");
    let file = std::fs::File::create(&path).expect("create sparse ROM");
    file.set_len(MAX_IMAGE_SIZE as u64 + 1)
        .expect("size sparse ROM");
    drop(file);
    for subcommand in ["cartridge", "boot"] {
        let output = run(&["megadrive", subcommand, "--rom", path_str(&path)]);
        let stderr = String::from_utf8(output.stderr).expect("utf8");
        assert!(
            !output.status.success(),
            "`megadrive {subcommand}` must reject an oversized ROM"
        );
        assert!(
            stderr.contains("64 MiB"),
            "the oversized error must name the mapper ceiling:\n{stderr}"
        );
    }
    let _ = std::fs::remove_dir_all(&dir);
}
